mapper.select:
select  from marketing_product_order
where primary_registration_id = #{registrationId}
order by id desc limit 1

mapper.update:
update marketing_product_order
set fulfillment_state = #{state}, update_time = #{updateTime}
where id = #{id} and status = 1

mapper.select:
select  from marketing_product_order
where member_id = #{memberId}
order by id desc limit #{limit}

mapper.update:
update marketing_product_order
set registration_ids_json = case
        when registration_ids_json is null or registration_ids_json = '' then json_array(#{registrationId})
        else json_array_append(registration_ids_json, '$', #{registrationId})
    end,
    update_time = #{updateTime}
where id = #{id}

update marketing_product_order
set status = 2, update_time = #{updateTime}
where id = #{id} and status = 0

update marketing_product_order
set status = 3, revoked_reason = #{reason}, refunded_at = #{refundedAt}, update_time = #{updateTime}
where id = #{id} and status = 1
